export function faviconSpriteId(host) {
  return String(host || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

export function getFaviconSpriteClass(host) {
  const id = faviconSpriteId(host);
  return FAVICON_SPRITE_HOSTS.has(id) ? `source-icon-${id}` : '';
}
